style.css:
@-moz-document domain("pinterest.com") {
/* 1. THE REFINED PALETTE */
    :root {
        --nea-vanilla: #FDF5E6 !important;   /* Old Lace / Custard (Not White) */
        --nea-strawberry: #FFB7C5 !important;/* Soft Pink */
        --nea-chocolate: #5D4037 !important; /* Dark Cocoa */
        --nea-font: 'Lexend', 'Quicksand', sans-serif;
    }

    /* 2. FORCE COLORS ON EVERYTHING */
    /* This targets every div and background to kill the white */
    *, ::before, ::after {
        border-color: var(--nea-chocolate) !important;
        font-family: var(--nea-font) !important;
    }

    /* Backgrounds: Kill all white/gray */
    html, body, div, section, nav, [role="main"], [role="navigation"] {
        background-color: var(--nea-vanilla) !important;
    }

    /* Text: Kill all black/gray */
    h1, h2, h3, h4, h5, h6, p, span, div, li, a, input {
        color: var(--nea-chocolate) !important;
    }

    /* 3. STRAWBERRY ACCENTS (The 'Red' parts) */
    /* Targets Pinterest's signature red buttons and dots */
    div[style*="background-color: rgb(230, 0, 35)"],
    div[style*="background-color: #e60023"],
    button[class*="red"],
    [data-test-id="pdp-buy-it-button"],
    [data-test-id="save-button"] {
        background-color: var(--nea-strawberry) !important;
        border: 2px solid var(--nea-chocolate) !important;
    }

    /* 4. PIN CARDS */
    /* Making pins look like little treats */
    [data-test-id="pin"] {
        background-color: var(--nea-vanilla) !important;
        border: 3px solid var(--nea-chocolate) !important;
        border-radius: 24px !important;
        padding: 8px !important;
    }

    img {
        border-radius: 16px !important;
        border: 2px solid var(--nea-strawberry) !important;
    }

    /* 5. SEARCH & HEADER */
    [data-test-id="header-background"] {
        background-color: var(--nea-vanilla) !important;
        border-bottom: 5px solid var(--nea-strawberry) !important;
    }

    [data-test-id="search-box-input"] {
        background-color: #F5E6D3 !important; /* Slightly darker vanilla */
        border: 2px solid var(--nea-chocolate) !important;
    }

    /* 6. ICONS & SVGS */
    svg {
        fill: var(--nea-chocolate) !important;
        color: var(--nea-chocolate) !important;
    }

    /* 7. SCROLLBARS (Chocolate & Strawberry) */
    ::-webkit-scrollbar { width: 12px; height: 12px; }
    ::-webkit-scrollbar-track { background: var(--nea-chocolate); }
    ::-webkit-scrollbar-thumb { 
        background: var(--nea-strawberry); 
        border-radius: 10px;
        border: 2px solid var(--nea-chocolate);
    }
}
